package com.bank.state.producer;

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;

@Component
@Slf4j
public class StatePublisher {

    private final KafkaProducer<String, String> producer;

    public StatePublisher(KafkaProducer<String, String> producer) { this.producer = producer; }

    public void publishState(String accountId, String snapshot) {
        // Guard: on a compacted topic a null/blank key is NOT protected by compaction.
        if (accountId == null || accountId.isBlank()) {
            throw new IllegalArgumentException("Compacted topic requires a non-null key");
        }
        producer.send(new ProducerRecord<>("account.state", accountId, snapshot));
        log.info("Published state for {}", accountId);
    }

    public void deleteState(String accountId) {
        // Tombstone: null value marks the key for deletion (removed after delete.retention.ms).
        producer.send(new ProducerRecord<>("account.state", accountId, null));
        log.info("Tombstone published for {} (will fully disappear after delete.retention.ms)", accountId);
    }
}
