package com.bank.state.demo;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CompactionDisappearanceDemo {

    private static final Logger log = Logger.getLogger(CompactionDisappearanceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Cleaner cleaner = new Cleaner();

        log.info("=== Reason 1: tombstone expires after delete.retention.ms ===");
        CompactedTopic t1 = new CompactedTopic(new TopicConfig("compact", 86400000L, 0.5, 86400000L));
        t1.append("SAV2001", "state-v1", 0);
        t1.append("SAV2001", null, 1000);                 // tombstone at t=1s
        cleaner.clean(t1, /*nowMs*/ 90_000_000L, log);    // 25h later
        log.info("SAV2001 present? " + t1.hasKey("SAV2001") + " (expected false — tombstone aged out)");

        log.info("=== Reason 2: compact,delete expires even the latest record by age ===");
        CompactedTopic t2 = new CompactedTopic(new TopicConfig("compact,delete", 86400000L, 0.5, 86400000L));
        t2.config.retentionMs = 3_600_000L;               // 1h time retention ALSO applies
        t2.append("DORMANT9999", "latest-snapshot", 0);   // last update long ago
        cleaner.clean(t2, /*nowMs*/ 7_200_000L, log);     // 2h later
        log.info("DORMANT9999 latest present? " + t2.hasKey("DORMANT9999")
                + " (expected false — expired by time retention despite being latest)");

        log.info("=== Reason 3: null-key records are not compactable, deleted by retention ===");
        CompactedTopic t3 = new CompactedTopic(new TopicConfig("compact,delete", 86400000L, 0.5, 3_600_000L));
        t3.append(null, "orphan-event", 0);               // null key: bypasses compaction
        cleaner.clean(t3, /*nowMs*/ 7_200_000L, log);
        log.info("orphan null-key record present? " + t3.hasNullKeyRecord()
                + " (expected false — never protected by compaction)");

        log.info("=== Reason 4: aggressive settings purge old versions almost immediately ===");
        CompactedTopic t4 = new CompactedTopic(new TopicConfig("compact", 86400000L, 0.01, 60000L));
        t4.append("CUR3001", "old-version", 0);
        t4.append("CUR3001", "new-version", 100);
        cleaner.clean(t4, /*nowMs*/ 200L, log);           // runs almost instantly
        log.info("CUR3001 old-version still findable? " + t4.hasValue("CUR3001", "old-version")
                + " (expected false — aggressive compaction removed it at once)");
    }
}

// ─── Would be in Record.java in a real project ───
class Record {
    final String key; final String value; final long timestampMs;
        Record(String key, String value, long timestampMs) { this.key = key;
        this.value = value
        this.timestampMs = timestampMs; }
    boolean isTombstone() { return value == null && key != null; }
}

// ─── Would be in TopicConfig.java in a real project ───
class TopicConfig {
    final String cleanupPolicy;          // "compact" or "compact,delete"
    final long deleteRetentionMs;
    final double minCleanableDirtyRatio;
    long retentionMs;                    // only applies if policy contains "delete"
    TopicConfig(String cleanupPolicy, long deleteRetentionMs, double ratio, long retentionMs) {
            this.cleanupPolicy = cleanupPolicy;
            this.deleteRetentionMs = deleteRetentionMs;
            this.minCleanableDirtyRatio = ratio;
            this.retentionMs = retentionMs;
    }
    boolean alsoDeletes() { return cleanupPolicy.contains("delete"); }
}

// ─── Would be in CompactedTopic.java in a real project ───
class CompactedTopic {
    final TopicConfig config;
    final List<Record> records = new ArrayList<>();
    CompactedTopic(TopicConfig config) { this.config = config; }

    void append(String key, String value, long ts) { records.add(new Record(key, value, ts)); }

    boolean hasKey(String key) {
        for (Record r : records) if (key.equals(r.key) && r.value != null) return true;
        return false;
    }
    boolean hasValue(String key, String value) {
        for (Record r : records) if (key.equals(r.key) && value.equals(r.value)) return true;
        return false;
    }
    boolean hasNullKeyRecord() {
        for (Record r : records) if (r.key == null) return true;
        return false;
    }
}

// ─── Would be in Cleaner.java in a real project ───
class Cleaner {
    void clean(CompactedTopic t, long nowMs, Logger log) {
        Map<String, Record> latest = new LinkedHashMap<>();
        List<Record> survivors = new ArrayList<>();

        // Compaction: keep latest per non-null key.
        for (Record r : t.records) {
            if (r.key != null) latest.put(r.key, r);
        }
        for (Record r : t.records) {
            boolean keep = true;
            // Reason 3: null-key records are not compactable; only retention governs them.
            if (r.key == null) {
                keep = !(t.config.alsoDeletes() && nowMs - r.timestampMs > t.config.retentionMs);
            } else if (r.isTombstone()) {
                // Reason 1: tombstone removed after delete.retention.ms.
                keep = nowMs - r.timestampMs <= t.config.deleteRetentionMs;
            } else if (latest.get(r.key) != r) {
                // Reason 4: superseded old version removed by compaction (aggressively here).
                keep = false;
            } else if (t.config.alsoDeletes() && nowMs - r.timestampMs > t.config.retentionMs) {
                // Reason 2: compact,delete expires even the latest by age.
                keep = false;
            }
            if (keep) survivors.add(r);
        }
        t.records.clear();
        t.records.addAll(survivors);
        log.info("Cleaned: policy=" + t.config.cleanupPolicy + " survivors=" + survivors.size());
    }
}

